command:
cat > /etc/nginx/conf.d/fleet-tls.conf <<'EOF'
server {
    listen 8443 ssl;
    server_name node2;

    ssl_certificate     /etc/pki/tls/fleet-ca/node2.cert.pem;
    ssl_certificate_key /etc/pki/tls/fleet-ca/node2.key.pem;

    location / {
        return 200 "fleet-internal-ca tls ok\n";
        default_type text/plain;
    }
}
EOF
nginx -t

